values
  ('physics-board-dinajpur-2019-mcq-011', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'মুক্তভাবে পড়ন্ত বস্তুর ক্ষেত্রে- i. ত্বরণ অপরিবর্তিত থাকে ii. বেগ সময়ের সমানুপাতিক iii. সরণ সময়ের সমানুপাতিক নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"i ও ii","ঘ":"i ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-012', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'উড়ন্ত পাখির মধ্যে কোন ঘর্ষণ ক্রিয়াশীল?', 'mcq', '{"ক":"আবর্ত ঘর্ষণ","খ":"পিছলানো ঘৰ্ষণ","গ":"স্থিতি ঘর্ষণ","ঘ":"প্রবাহী ঘর্ষণ"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-013', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'নিচের কোন ক্ষেত্রে উত্তল দর্পণ ব্যবহার করা হয়?', 'mcq', '{"ক":"ওভারহেড প্রজেক্টরে","খ":"প্রতিফলক টেলিস্কোপে","গ":"কান ও গলার পরীক্ষায়","ঘ":"স্টিমারের সার্চলাইটে"}'::jsonb, 'ক', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-014', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'বায়োগ্যাস উৎপাদনে গোবর ও পানির মিশ্রণের অনুপাত হলো-', 'mcq', '{"ক":"১ : ২","খ":"২ : ১","গ":"২ : ৩","ঘ":"৪ : ৫"}'::jsonb, 'ক', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-015', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'রক্তের শ্বেত কণিকার অত্যধিক বৃদ্ধির ফলে রক্তস্বল্পতা রোগের চিকিৎসায় ব্যবহৃত হয় কোন আইসোটোপ ?', 'mcq', '{"ক":"ফসফরাস-32","খ":"আয়োডি-131","গ":"কোবাল্ট-60","ঘ":"টেকনিশিয়ান-99"}'::jsonb, 'ক', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-016', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'পানির উপরিতল থেকে একই গভীরতায় কোন জলাশয়ে বেশি চাপ অনুভূ ত হবে?', 'mcq', '{"ক":"পুকু র","খ":"নদী","গ":"সমুদ্র","ঘ":"হাওড়"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-017', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'সকল বস্তুর ভর সমান হলে এবং তাপমাত্রা 1 k কমাতে চাইলে নিচের কোন বস্তু বেশি তাপ হারাবে?', 'mcq', '{"ক":"জলীয় বাষ্প","খ":"বিশুদ্ধ পানি","গ":"তামার পাত","ঘ":"রূপার গয়না"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-018', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'একটি ট্রান্সফর্মারের মুখ্য কু ণ্ডলীর ভোল্টেজ 24 V এবং প্রবাহ 2 A । গৌণ কু ণ্ডলীর প্রবাহ 6 A হলে, গৌণ কু ণ্ডলীর ভোল্টেজ কত?', 'mcq', '{"ক":"0.0139 V","খ":"0.125 V","গ":"8 V","ঘ":"72 V"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-019', 'class9-physics-bn-guide', 'satt-physics-board.pdf p180', 'বাতাসে শব্দের বেগ 350ms-1 । একটি বস্তু বাতাসে যে শব্দ সৃষ্টি করে তার তরঙ্গদৈর্ঘ্য 1250 cm । এর পর্যায়কাল কত?', 'mcq', '{"ক":"28 s","খ":"3.571 s","গ":"0.28 s","ঘ":"0.0357s"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, null, 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-020', 'class9-physics-bn-guide', 'satt-physics-board.pdf p181', 'বস্তুটির দৈর্ঘ্য প্রসারণ সহগ কত?', 'mcq', '{"ক":"6.25 ×10 −6 K −1","খ":"2.083 ×10 −6 K −1","গ":"3.125 ×10 −6 K −1","ঘ":"4.166 ×10 −6 K −1"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, 'পানি ও কেরোসিনে অদ্রবণীয় একটি কঠিন বস্তুর ভর 68 gm এবং আয়তন 80 ঘন সে.মি.। তাপমাত্রা 30°C বাড়ালে বস্তুটির আয়তন 80.015 ঘন সে.মি. হয়। পানির ঘনত্ব 1000 kg m-3 এবং কেরোসিনের ঘনত্ব 810 kg m-3 ।', 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-021', 'class9-physics-bn-guide', 'satt-physics-board.pdf p181', 'কঠিন বস্তুটি—', 'mcq', '{"ক":"পানিতে ভাসবে কিন্তু কেরোসিনে ডু ববে","খ":"কেরোসিনে নিমজ্জিত অবস্থায় ভাসবে","গ":"পানি ও কেরোসিন উভয় তরলে ভাসবে","ঘ":"পানি ও কেরোসিন উভয় তরলে ডু ববে"}'::jsonb, 'ক', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, 'পানি ও কেরোসিনে অদ্রবণীয় একটি কঠিন বস্তুর ভর 68 gm এবং আয়তন 80 ঘন সে.মি.। তাপমাত্রা 30°C বাড়ালে বস্তুটির আয়তন 80.015 ঘন সে.মি. হয়। পানির ঘনত্ব 1000 kg m-3 এবং কেরোসিনের ঘনত্ব 810 kg m-3 ।', 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-022', 'class9-physics-bn-guide', 'satt-physics-board.pdf p181', 'আধানদ্বয়ের মধ্যবর্তী বিকর্ষণ বল কত?', 'mcq', '{"ক":"1. 08 × 10 10 N","খ":"5. 4 × 10 11 N","গ":"5. 4 × 10 13 N","ঘ":"1. 08 × 10 14 N"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, 'নিচের দুটি আধানকে অসীম দূরত্ব হতে তড়িৎক্ষেত্রের কোনো বিন্দুতে আনতে। একই পরিমাণ কাজ করতে হয়।', 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-023', 'class9-physics-bn-guide', 'satt-physics-board.pdf p181', 'একটি পরিবাহী তার দ্বারা আধান দুটিকে সংযুক্ত করলে- i. A হতে কিছু আধান B তে যাবে ii. B হতে কিছু আধান A তে যাবে iii. বিভব সমান না হওয়া পর্যন্ত আধানের প্রবাহ চলবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"ii ও iii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, 'নিচের দুটি আধানকে অসীম দূরত্ব হতে তড়িৎক্ষেত্রের কোনো বিন্দুতে আনতে। একই পরিমাণ কাজ করতে হয়।', 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-024', 'class9-physics-bn-guide', 'satt-physics-board.pdf p182', 'লেন্সটির ক্ষমতা কত?', 'mcq', '{"ক":"+0.1 D","খ":"+5D","গ":"+6.67 D","ঘ":"+10 D"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, 'লেন্সটির বক্রতার ব্যাসার্ধ 20 cm', 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2019-mcq-025', 'class9-physics-bn-guide', 'satt-physics-board.pdf p182', 'AB বস্তুটির প্রতিবিম্ব হবে- i. বাস্তব ও উল্টা ii. অবাস্তব ও সোজা iii. AB হতে বড় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"i ও iii","ঘ":"ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2019-mcq', false, 'board-mcq', null, 'লেন্সটির বক্রতার ব্যাসার্ধ 20 cm', 'dinajpur', 2019, true),
  ('physics-board-dinajpur-2020-mcq-001', 'class9-physics-bn-guide', 'satt-physics-board.pdf p133', 'কোন চিত্রে তিনটি রোধ সমান্তরালে সংযুক্ত?', 'mcq', '{"ক":"","খ":"","গ":"","ঘ":""}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', 'অপশন চিহ্ন (a/b/c/d) টেক্সটে পাওয়া যায়নি (সম্ভবত চিত্র আকারে); ক অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); খ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); গ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); ঘ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-002', 'class9-physics-bn-guide', 'satt-physics-board.pdf p133', 'মাইক্রোফোনে শক্তির কী রকম রূপান্তর হয়?', 'mcq', '{"ক":"তড়িৎ শক্তি → শব্দ শক্তি","খ":"শব্দ শক্তি → যান্ত্রিক শক্তি","গ":"যান্ত্রিক শক্তি → শব্দ শক্তি","ঘ":"শব্দ শক্তি → তড়িৎ শক্তি"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-003', 'class9-physics-bn-guide', 'satt-physics-board.pdf p133', 'R1 = R2 = R3 = R4 = 4Ω এই রোধগুলো কিভাবে সাজালে তু ল্য রোধের মান 5.33 হবে?', 'mcq', '{"ক":"চারটিকে সমান্তরালে যুক্ত করলে","খ":"দুটি সমান্তরাল ও দুটি শ্রেণিতে যুক্ত করলে","গ":"তিনটি সমান্তরাল ও একটি শ্রেণিতে যুক্ত করলে","ঘ":"তিনটি শ্রেণি ও একটি সমান্তরালে যুক্ত করলে"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-004', 'class9-physics-bn-guide', 'satt-physics-board.pdf p133', 'কোনটি পরিবাহকত্বের একক?', 'mcq', '{"ক":"(Ωm) −1","খ":"m","গ":"Ω","ঘ":"Ωm"}'::jsonb, 'ক', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-005', 'class9-physics-bn-guide', 'satt-physics-board.pdf p133', 'বাতাসে আলফা কণার গতিপথ কীরূপ?', 'mcq', '{"ক":"সর্পিলাকার","খ":"সরলরৈখিক","গ":"এলোমেলো","ঘ":"বৃত্তাকার"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-006', 'class9-physics-bn-guide', 'satt-physics-board.pdf p134', 'পরিবাহী তারের কু ণ্ডলীর মধ্যে চৌম্বকক্ষেত্রের পরিবর্তন করে কোনটি তৈরি করা হয়েছে?', 'mcq', '{"ক":"বৈদ্যুতিক মোটর","খ":"ট্রান্সফর্মার","গ":"বিদ্যুৎ জেনারেটর","ঘ":"ট্রানজিস্টর"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-007', 'class9-physics-bn-guide', 'satt-physics-board.pdf p134', 'একটি ট্রান্সফর্মারে মুখ্য কু ণ্ডলীর পাকসংখ্যা 18 এবং গৌণ কু ণ্ডলীর পাকসংখ্যা 90। গৌণ কু ণ্ডলীর তড়িৎ প্রবাহ 0.5 A । মুখ্য কু ণ্ডলীর প্রবাহ কত?', 'mcq', '{"ক":"0.1 A","খ":"0.5 A","গ":"2 A","ঘ":"2.5 A"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p134', 'কোনটিতে শরীরে রেডিও ফ্রিকোয়েন্সির বিদ্যুৎ চু ম্বকীয় তরঙ্গ দেওয়া হয়?', 'mcq', '{"ক":"এক্সরে","খ":"আল্ট্রাসনোগ্রাফি","গ":"সিটি স্ক্যান","ঘ":"এমআরআই"}'::jsonb, 'ঘ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
  ('physics-board-dinajpur-2020-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p134', 'এনালগ সংকেত ব্যবহারের ফলে- i. নয়েজ বাড়ে ii. সংকেত বিবর্ধিত হয় iii. সংকেত হারিয়ে যাওয়ার সম্ভাবনা থাকে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"ii ও iii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2020-mcq', false, 'board-mcq', null, null, 'dinajpur', 2020, true),
