  ('physics-board-dinajpur-2023-mcq-011', 'class9-physics-bn-guide', 'satt-physics-board.pdf p151', 'বিনা বাধায় পড়ন্ত বস্তুর ক্ষেত্রে সম্পর্কগুলো হলো- i. v1 v2 = t1 t2 ii. v1 v2 = h1 h2 iii. 2 h1 t1 = 2 h2 t2 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i, ii","খ":"i, iii","গ":"ii, iii","ঘ":"i, ii, iii"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2023-mcq', false, 'board-mcq', null, null, 'dinajpur', 2023, true),
