  ('physics-board-dinajpur-2024-mcq-024', 'class9-physics-bn-guide', 'satt-physics-board.pdf p16', 'বরফের তাপমাত্রা 0°C এ উন্নীত হতে কত তাপের প্রয়োজন?', 'mcq', '{"ক":"420 J −1 kg −1 K −1","খ":"4200 J kg − K −1","গ":"420000 J kg −1 K −1","ঘ":"33400 J kg −1 K −1"}'::jsonb, 'খ', 1, false, 'physics-board-dinajpur-2024-mcq', false, 'board-mcq', null, '100 gm ভরের বরফকে তাপ প্রয়োগ করা হলো: বরফের আপেক্ষিক তাপ 2100 Jkg-1K-1', 'dinajpur', 2024, true),
  ('physics-board-dinajpur-2024-mcq-025', 'class9-physics-bn-guide', 'satt-physics-board.pdf p16', 'পদার্থের অণুসমূহের- i. CD অংশের গতিশক্তি সবচেয়ে কম ii. BC অংশে বিভবশক্তি বৃদ্ধি পাচ্ছে iii. AB অংশে গতিশক্তি তাপমাত্রার সমানুপাতিক নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-dinajpur-2024-mcq', false, 'board-mcq', null, '100 gm ভরের বরফকে তাপ প্রয়োগ করা হলো: বরফের আপেক্ষিক তাপ 2100 Jkg-1K-1', 'dinajpur', 2024, true),
