  ('physics-board-mymensingh-2022-mcq-007', 'class9-physics-bn-guide', 'satt-physics-board.pdf p40', 'একটি হাইড্রোলিক প্রেসের ছোট ও বড় পিস্টনের ক্ষেত্রফল যথাক্রমে 10 cm2 ও 350 cm2। ছোট পিস্টনে 100 N বল প্রয়োগ করলে বড় পিস্টনে কত বল পাওয়া যাবে?', 'mcq', '{"ক":"20 N","খ":"3500 N","গ":"5000 N","ঘ":"10000 N"}'::jsonb, 'খ', 1, false, 'physics-board-mymensingh-2022-mcq', false, 'board-mcq', 'ব্যাখ্যা: লেবেল আছে কিন্তু ব্যাখ্যার পাঠ টেক্সটে পাওয়া যায়নি', null, 'mymensingh', 2022, true),
