  ('physics-board-jessore-2022-mcq-025', 'class9-physics-bn-guide', 'satt-physics-board.pdf p86', 'AB কে দর্পণ থেকে 6 cm পিছনে আনা হলে- i. অবাস্তব ও সোজা বিম্ব গঠন করে ii. বাস্তব ও উল্টো বিম্ব গঠন করে iii. বক্রতার কেন্দ্রে ও লক্ষ্যবস্তুর সমান নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"ii ও iii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2022-mcq', false, 'board-mcq', null, null, 'jessore', 2022, true),
