  ('physics-board-jessore-2023-mcq-003', 'class9-physics-bn-guide', 'satt-physics-board.pdf p65', 'একটি শিশু দোলনায় দুলছে। এর গতি — i. ঘূর্ণন গতি ii. পর্যায়বৃত্ত গতি iii. স্পন্দন গতি নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-004', 'class9-physics-bn-guide', 'satt-physics-board.pdf p65', 'এক টু করা সাধারণ কাঁচে কী পরিমাণ আলো প্রতিফলিত হয়?', 'mcq', '{"ক":"২% - ৩%","খ":"৩% - ৪%","গ":"8% - ৫%","ঘ":"৫% - ৬%"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-005', 'class9-physics-bn-guide', 'satt-physics-board.pdf p65', 'একটি পানিশুন্য কূ পের গভীরতা 25m । এতে সর্বোচ্চ কত উচ্চতায় পানি থাকলে প্রতিধ্বনি শোনা যাবে?', 'mcq', '{"ক":"0m","খ":"8.5 m","গ":"16.5m","ঘ":"25 m"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-006', 'class9-physics-bn-guide', 'satt-physics-board.pdf p65', 'প্লাজমা —-- i. পদার্থের চতু র্থ অবস্থা ii. কণাগুলো তড়িৎ বহন করে iii.কণাগুলোর নির্দিষ্ট আকার ও আয়তন আছে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
