  ('physics-board-jessore-2023-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p66', 'কোন দেশে বায়োফু য়েল ব্যাপক আকারে ব্যবহৃত হচ্ছে?', 'mcq', '{"ক":"কানাডা","খ":"ব্রাজিল","গ":"চীন","ঘ":"জাপান"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p66', 'অবতল দর্পণে অবাস্তব প্রতিবিম্ব পেতে হলে লক্ষবস্তুকে কোথায় রাখতে হবে?', 'mcq', '{"ক":"2F এ","খ":"F ও 2F এর মাঝে","গ":"P ও F এর মাঝে","ঘ":"2F ও অসীমের মাঝে"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
